; ============================================================
; Chrono Trigger (SNES) — the code source
;
; The 65816 code, the SPC700 driver and the packed $C3 module.
; `make build` assembles asm/rom.asm, which includes this file and
; then the data layer (asm/data/, generated by tools/extract_data.py)
; onto a blank image; nothing comes from a copy of the original ROM.
; The tools that measure the code (tools/verify.py, progress.py,
; xref.py, draft.py) assemble this file alone.
; ============================================================

; --- Shared names (no bytes emitted) ---
; Defines must be visible before any bank uses them.

incsrc "include/constants.inc"
incsrc "include/constants_engine.inc"
incsrc "include/constants_battle.inc"
incsrc "include/ram_engine.inc"
incsrc "include/ram_battle.inc"
incsrc "include/constants_menu.inc"
incsrc "include/ram_menu.inc"
incsrc "include/macros.inc"
incsrc "spc700/spc700.inc"

; --- Bank includes ---
; Every bank with code; the data in the other banks, and between the
; code, is the data layer's (asm/data/).

incsrc "bank00/bank00.asm"
incsrc "bankC0/bankC0.asm"
incsrc "bankC1/bankC1.asm"
incsrc "bankCC/bankCC.asm"
incsrc "bankCD/bankCD.asm"
incsrc "bankCE/bankCE.asm"

incsrc "bankC2/bankC2.asm"
incsrc "bankC3/bankC3.asm"
incsrc "bankC6/bankC6.asm"
incsrc "bankC7/bankC7.asm"
incsrc "spc700/driver.asm"
incsrc "bankCF/bankCF.asm"
incsrc "bankD1/bankD1.asm"
; incsrc "bank01/bank01.asm"
; incsrc "bank02/bank02.asm"
incsrc "bankFD/bankFD.asm"
incsrc "bankFF/bankFF.asm"

; --- Names for not-yet-matched routines (label-only, no bytes) ---
incsrc "include/unmatched.asm"
incsrc "include/unmatched_battle.asm"
